import type { Product } from '../catalog';
import { DECK_INFO } from './data';

/**
 * Playing-card decks — the flagship merch (generated by scripts/merch/decks, see merch-print/decks/README.md).
 * Every deck is a Product with category 'cards'. Only `import type` from ../catalog here (catalog imports this file).
 *
 * The Signature deck keeps the historical id 'deck' (old links / sign-ups keep working) and is the store hero.
 * Copy: DECK_STRINGS (./strings) · in-game twin backs: DECK_COSMETICS (./cosmetics) · facts: DECK_INFO (./data).
 */
export const deckMockup = (deckId: string, shot: 'hero' | 'fan' | 'spread' | 'backs') => `/merch/decks/${deckId}/mockups/${shot}.webp`;
/** Small faces for the 3D box viewer: 'box-front' | 'box-back' | 'box-side' | 'box-top' | 'back' | card ids (AS, KH, QS, JD, …). */
export const deckWeb = (deckId: string, name: string) => `/merch/decks/${deckId}/web/${name}.webp`;

export const DECK_PRODUCTS: Product[] = DECK_INFO.map(d => ({
  id: d.productId,
  category: 'cards',
  price: d.price,
  // relative to public/merch/designs/ → public/merch/decks/<id>/<card>.svg (the deck's signature card, vector)
  design: `../decks/${d.id}/${d.heroCard}`,
  colours: [{ id: d.colour, swatch: d.swatch, images: (['hero', 'fan', 'spread', 'backs'] as const).map(s => deckMockup(d.id, s)) }],
  ...(d.hero ? { hero: true } : {}),
  ...(d.badge ? { badge: d.badge } : {}),
}));

/** Product id → UI languages the deck is designed for (store: show matching decks first). */
export const DECK_MARKETS: Record<string, string[]> = Object.fromEntries(DECK_INFO.map(d => [d.productId, [...d.markets]]));

/** Deck products ordered for a visitor: decks made for their language first, then the rest (stable). */
export function decksForLang(lang: string, products: Product[] = DECK_PRODUCTS): Product[] {
  const score = (p: Product) => {
    const m = DECK_MARKETS[p.id] ?? [];
    if (p.hero) return 0;                                   // the Signature deck always leads
    if (m.length < 17 && m.includes(lang)) return 1;        // made for this market
    return 2;
  };
  return products.map((p, i) => ({ p, i })).sort((a, b) => score(a.p) - score(b.p) || a.i - b.i).map(x => x.p);
}
export { DECK_STRINGS } from './strings';
